const roles:Record<string,string>={president:"단장",vice_president:"부단장",secretary:"서기",treasurer:"회계",member:"단원",curia_president:"상위 꾸리아 단장",visitor:"가입 전"};
const organizationStatuses:Record<string,string>={draft:"작성중",requested:"승인 대기중",approved:"활동중",rejected:"반려",ended:"종료"};
function esc(v:unknown){const d=document.createElement("div");d.textContent=String(v??"");return d.innerHTML}
async function api<T>(url:string,options?:RequestInit){
  const editForm=document.querySelector<HTMLFormElement>(".member-legion-edit form");
  if(options?.method==="POST"&&/\/api\/parishioner\/legion\/organizations\/\d+\/edit-requests$/.test(url)&&editForm?.dataset.onlyIcon==="true"){
    const payload=JSON.parse(String(options.body??"{}")) as{iconType?:string;iconData?:string};
    const organizationId=url.match(/organizations\/(\d+)/)?.[1];
    const iconResponse=await fetch(`/api/parishioner/legion/organizations/${organizationId}/icon`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({iconType:payload.iconType,iconData:payload.iconData})});
    const iconResult=await iconResponse.json() as T&{message?:string};
    if(!iconResponse.ok)throw new Error(iconResult.message??"조직 아이콘을 변경하지 못했습니다.");
    return iconResult;
  }
  if(options?.method==="POST"&&/\/api\/parishioner\/legion\/organizations\/\d+\/posts$/.test(url)){
    const file=document.querySelector<HTMLInputElement>('.legion-content-modal .legion-post-form input[name="attachment"]')?.files?.[0];
    if(file){if(file.size>5*1024*1024)throw new Error("첨부파일은 5MB 이하의 파일 1개만 등록할 수 있습니다.");const payload=JSON.parse(String(options.body??"{}"));payload.attachment={name:file.name,type:file.type||"application/octet-stream",data:await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]??"");reader.onerror=()=>reject(new Error("첨부파일을 읽지 못했습니다."));reader.readAsDataURL(file)})};options={...options,body:JSON.stringify(payload)}}
  }
  const response=await fetch(url,{...options,headers:{"Content-Type":"application/json",...(options?.headers??{})}});
  const responseText=await response.text();let data:T&{message?:string;id?:number};try{data=JSON.parse(responseText) as T&{message?:string;id?:number}}catch{throw new Error(response.ok?"서버 응답을 처리하지 못했습니다.":"요청을 처리할 수 없습니다. 서버 반영 상태를 확인해 주세요.")}
  if(!response.ok)throw new Error(data.message??"요청 실패");
  if(url==="/api/parishioner/legion/organizations"&&options?.method==="POST"&&data.id){
    const file=document.querySelector<HTMLInputElement>('.member-legion-create [data-legion-icon]')?.files?.[0];
    if(file){
      if(file.size>2*1024*1024)throw new Error("조직 아이콘은 2MB 이하 이미지를 선택해 주세요.");
      const iconData=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]??"");reader.onerror=()=>reject(new Error("아이콘 이미지를 읽지 못했습니다."));reader.readAsDataURL(file)});
      const iconResponse=await fetch(`/api/parishioner/legion/organizations/${data.id}/icon`,{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({iconType:file.type,iconData})});
      if(!iconResponse.ok){const error=await iconResponse.json() as{message?:string};throw new Error(error.message??"조직 아이콘을 저장하지 못했습니다.")}
    }
  }
  return data;
}
function panel(){let p=document.querySelector<HTMLElement>(".member-legion");if(p)return p;p=document.createElement("section");p.className="member-legion";p.hidden=true;p.innerHTML='<header><div><small>LEGIO MARIAE</small><h2>레지오마리에</h2></div><button class="green-button" type="button">+ 조직 생성</button></header><div></div>';document.querySelector<HTMLElement>("main")!.append(p);p.querySelector("button")!.onclick=create;return p}
async function show(){document.querySelectorAll<HTMLElement>("main>section").forEach(s=>s.hidden=true);const p=panel();p.hidden=false;const list=p.lastElementChild as HTMLElement;try{const [items,profile]=await Promise.all([api<Org[]>("/api/parishioner/legion/organizations"),api<{name:string;baptismalName:string|null}>("/api/parishioner/profile")]);list.innerHTML=items.length?items.map(o=>{const presidentName=o.presidentName||(o.role==="president"?profile.name:null),presidentBaptismalName=o.presidentBaptismalName||(o.role==="president"?profile.baptismalName:null),directMember=o.role!=="curia_president";return`<article class="legion-${o.organizationType} ${o.hasIcon?"has-icon":""}">${o.hasIcon?`<img class="legion-card-icon" src="/api/parishioner/legion/organizations/${o.id}/icon" alt="${esc(o.name)} 아이콘">`:""}<header><b>${o.organizationType==="curia"?"꾸리아":"쁘레시디움"}</b></header><div class="legion-card-title"><h3>${esc(o.name)}</h3><span class="legion-card-status ${o.status}">${organizationStatuses[o.status]??esc(o.status)}</span></div>${o.parentName?`<small>상위 꾸리아 · ${esc(o.parentName)}</small>`:""}<p class="legion-card-president"><b>단장</b><span>${esc(presidentName??"정보 없음")}${presidentBaptismalName?` <em>(${esc(presidentBaptismalName)})</em>`:""}</span></p><p>${esc(o.description??"-")}</p>${directMember?`<nav class="legion-card-actions"><button data-legion-view="notice" data-org="${o.id}" data-name="${esc(o.name)}" type="button">공지사항</button><button data-legion-view="board" data-org="${o.id}" data-name="${esc(o.name)}" type="button">게시판</button><button data-legion-view="account" data-org="${o.id}" data-name="${esc(o.name)}" type="button">회계</button></nav>`:""}<footer>${roles[o.role]} · ${new Date(o.joinedAt).toLocaleDateString("ko-KR")}${o.role==="president"&&o.status!=="ended"?`<button data-edit-org="${o.id}" type="button">조직정보 수정</button>`:""}</footer></article>`}).join(""):'<p>소속되거나 승인 신청한 조직이 없습니다.</p>';list.querySelectorAll<HTMLButtonElement>("[data-edit-org]").forEach(button=>button.onclick=()=>void openOrganizationEdit(Number(button.dataset.editOrg)));list.querySelectorAll<HTMLButtonElement>("[data-legion-view]").forEach(button=>button.onclick=()=>void openLegionViewer(Number(button.dataset.org),button.dataset.name??"조직",button.dataset.legionView as "notice"|"board"|"account"))}catch(e){list.textContent=(e as Error).message}}
function customConfirm(name:string){return new Promise<boolean>(resolve=>{const layer=document.createElement("div");layer.className="member-modal legion-create-confirm";layer.innerHTML=`<section class="member-modal-box"><h3>조직 승인 신청</h3><div><strong>${esc(name)}</strong><p>승인 신청하시겠습니까?</p></div><footer><button data-choice="no" type="button">취소</button><button data-choice="yes" class="green-button" type="button">승인 신청</button></footer></section>`;document.body.append(layer);layer.querySelectorAll<HTMLButtonElement>("[data-choice]").forEach(button=>button.onclick=()=>{layer.remove();resolve(button.dataset.choice==="yes")})})}
