function personPicker(title:string,selected:Set<number>){return new Promise<Person|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal legion-person-picker";layer.innerHTML=`<section class="member-modal-box"><h3>${title} 지정</h3><div><div class="picker-search"><input type="search" placeholder="이름, 세례명 또는 이메일 (3글자 이상)"><button class="green-button" type="button">검색</button></div><div class="picker-results"><p>검색어를 3글자 이상 입력해 주세요.</p></div></div><footer><button type="button" data-close>취소</button></footer></section>`;document.body.append(layer);const input=layer.querySelector<HTMLInputElement>("input")!,results=layer.querySelector<HTMLElement>(".picker-results")!;let searchTimer=0,searchSequence=0;const close=()=>{clearTimeout(searchTimer);layer.remove();resolve(null)},search=async()=>{const q=input.value.trim(),sequence=++searchSequence;if(q.length<3){results.innerHTML="<p>검색어를 3글자 이상 입력해 주세요.</p>";return}results.innerHTML="<p>검색 중입니다.</p>";try{const people=await api<Person[]>(`/api/parishioner/legion/people?q=${encodeURIComponent(q)}`);if(sequence!==searchSequence)return;const available=people.filter(person=>!selected.has(person.id));results.innerHTML=available.map(person=>`<button type="button" data-person="${person.id}"><span><strong>${esc(person.name)}${person.baptismalName?` (${esc(person.baptismalName)})`:""}</strong><small>${esc(person.email)}</small></span><b>선택</b></button>`).join("")||"<p>선택할 수 있는 신도가 없습니다.</p>";results.querySelectorAll<HTMLButtonElement>("[data-person]").forEach((button,index)=>button.onclick=()=>{layer.remove();resolve(available[index]!)})}catch(error){if(sequence===searchSequence)results.textContent=(error as Error).message}};layer.querySelector("[data-close]")!.addEventListener("click",close);layer.querySelector<HTMLButtonElement>(".picker-search button")!.onclick=()=>{clearTimeout(searchTimer);void search()};input.oninput=()=>{clearTimeout(searchTimer);if(input.value.trim().length<3){searchSequence++;results.innerHTML="<p>검색어를 3글자 이상 입력해 주세요.</p>";return}searchTimer=window.setTimeout(()=>void search(),300)};input.onkeydown=event=>{if(event.key==="Enter"){event.preventDefault();clearTimeout(searchTimer);void search()}};input.focus()})}
function curiaPicker(curias:Curia[]){return new Promise<Curia|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal legion-person-picker";layer.innerHTML=`<section class="member-modal-box"><h3>상위 꾸리아 지정</h3><div><div class="picker-search"><input type="search" placeholder="꾸리아 명칭 또는 단장 검색"></div><div class="picker-results"></div></div><footer><button type="button" data-close>취소</button></footer></section>`;document.body.append(layer);const input=layer.querySelector<HTMLInputElement>("input")!,results=layer.querySelector<HTMLElement>(".picker-results")!,render=()=>{const q=input.value.trim().toLowerCase(),items=curias.filter(item=>`${item.name} ${item.presidentName} ${item.presidentBaptismalName??""}`.toLowerCase().includes(q));results.innerHTML=items.map(item=>`<button type="button"><span><strong>${esc(item.name)}</strong><small>단장 ${esc(item.presidentName)}${item.presidentBaptismalName?` (${esc(item.presidentBaptismalName)})`:""}</small></span><b>선택</b></button>`).join("")||"<p>검색된 꾸리아가 없습니다.</p>";results.querySelectorAll<HTMLButtonElement>("button").forEach((button,index)=>button.onclick=()=>{layer.remove();resolve(items[index]!)})};layer.querySelector("[data-close]")!.addEventListener("click",()=>{layer.remove();resolve(null)});input.oninput=render;render();input.focus()})}
