      body.innerHTML=`<div class="legion-account-summary"><span>이월금액<b>${opening.toLocaleString("ko-KR")}원</b></span><span>입금<b>${income.toLocaleString("ko-KR")}원</b></span><span>출금<b>${expense.toLocaleString("ko-KR")}원</b></span><span>잔액<b>${balance.toLocaleString("ko-KR")}원</b></span></div>${data.openingBalance===null?'<p class="legion-empty">아직 회계가 개설되지 않았습니다.</p>':data.entries.length?`<div class="legion-account-table"><table><thead><tr><th>일자</th><th>구분</th><th>항목</th><th>내용</th><th>금액</th><th>증빙</th><th>감사</th></tr></thead><tbody>${data.entries.map(item=>`<tr data-account-entry="${item.id}" class="${item.reportId?"":"editable"}"><td>${esc(item.entryDate)}</td><td>${item.direction==="income"?"입금":"출금"}</td><td>${esc(accountCategories[item.category]??item.category)}</td><td>${esc(item.description??"-")}</td><td class="${item.direction}">${item.amount.toLocaleString("ko-KR")}원</td><td>${item.receiptName?`<button class="legion-receipt-view" data-receipt="${item.id}" data-name="${esc(item.receiptName)}" type="button">보기</button>`:"-"}</td><td><b class="legion-audit ${item.auditStatus??"none"}">${item.auditStatus==="approved"?"승인":item.auditStatus==="rejected"?"반려":item.auditStatus==="requested"?"승인 대기":"미제출"}</b></td></tr>`).join("")}</tbody></table></div>`:'<p class="legion-empty">등록된 회계 내역이 없습니다.</p>'}`;
      body.querySelectorAll<HTMLTableRowElement>(":scope>.legion-account-table tbody tr").forEach((row,index)=>{const item=data.entries[index];if(item?.category==="praesidium_contribution"&&item.sourceOrganizationName)row.cells[2]!.textContent=`쁘레시디움-${item.sourceOrganizationName}`});body.querySelectorAll<HTMLButtonElement>("[data-receipt]").forEach(button=>button.onclick=event=>{event.stopPropagation();openLegionReceipt(Number(button.dataset.receipt),button.dataset.name??"증빙자료")});
