function legionRejectionReason(){return new Promise<string|null>(resolve=>{const layer=document.createElement("div");layer.className="member-modal legion-community-modal legion-rejection-modal";layer.innerHTML='<section class="member-modal-box"><h3>가입 요청 반려</h3><form class="member-modal-body"><label><b>* 반려 사유</b><textarea maxlength="1000" required placeholder="반려 사유를 작성해 주세요"></textarea></label><p data-error></p><footer><button type="button" data-close>취소</button><button class="green-button" type="submit" disabled>반려 진행</button></footer></form></section>';document.body.append(layer);const form=layer.querySelector<HTMLFormElement>("form")!,textarea=form.querySelector<HTMLTextAreaElement>("textarea")!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,close=()=>{layer.remove();resolve(null)};textarea.oninput=()=>submit.disabled=!textarea.value.trim();layer.querySelector("[data-close]")!.addEventListener("click",close);form.onsubmit=event=>{event.preventDefault();const reason=textarea.value.trim();if(!reason)return;layer.remove();resolve(reason)};textarea.focus()})}
function legionCommunityModal(title:string){const layer=document.createElement("div");layer.className="member-modal legion-community-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${esc(title)}</h3><div class="member-modal-body"><p class="legion-content-loading">불러오는 중...</p></div><footer><button type="button" data-close>닫기</button></footer></section>`;document.body.append(layer);layer.querySelector("[data-close]")!.addEventListener("click",()=>layer.remove());return{layer,body:layer.querySelector<HTMLElement>(".member-modal-body")!}}
async function openLegionInquiries(id:number,name:string,canReply:boolean){const{body}=legionCommunityModal(`${name} · 문의사항`);const render=async()=>{try{const items=await api<LegionInquiry[]>(`/api/parishioner/legion/organizations/${id}/inquiries`);body.innerHTML=`<div class="legion-inquiry-list">${items.map(item=>`<article><header><strong>${esc(item.authorName)}${item.authorBaptismalName?` (${esc(item.authorBaptismalName)})`:""}</strong><time>${new Date(item.createdAt).toLocaleString("ko-KR")}</time></header><p>${esc(item.content)}</p>${item.response?`<section><b>답변 · ${esc(item.responderName??"")}${item.responderBaptismalName?` (${esc(item.responderBaptismalName)})`:""}</b><p>${esc(item.response)}</p></section>`:canReply?`<form data-reply="${item.id}"><textarea maxlength="3000" required placeholder="답변을 입력해 주세요"></textarea><button class="green-button" type="submit">답변 보내기</button></form>`:'<small>답변 대기중</small>'}</article>`).join("")||"<p class=\"legion-empty\">등록된 문의사항이 없습니다.</p>"}</div><form class="legion-inquiry-new"><textarea maxlength="3000" required placeholder="문의사항을 입력해 주세요"></textarea><button class="green-button" type="submit">문의 보내기</button></form><p data-error></p>`;body.querySelector<HTMLFormElement>(".legion-inquiry-new")!.onsubmit=async event=>{event.preventDefault();const form=event.currentTarget as HTMLFormElement,content=form.querySelector("textarea")!.value.trim();if(!content)return;if(!await legionPostDecision("문의사항을 보내시겠습니까?","보내기"))return;try{await api(`/api/parishioner/legion/organizations/${id}/inquiries`,{method:"POST",body:JSON.stringify({content})});await render()}catch(error){body.querySelector<HTMLElement>("[data-error]")!.textContent=(error as Error).message}};body.querySelectorAll<HTMLFormElement>("[data-reply]").forEach(form=>form.onsubmit=async event=>{event.preventDefault();const response=form.querySelector("textarea")!.value.trim();if(!response)return;if(!await legionPostDecision("답변을 보내시겠습니까?","답변 보내기"))return;try{await api(`/api/parishioner/legion/inquiries/${form.dataset.reply}/reply`,{method:"POST",body:JSON.stringify({response})});await render()}catch(error){body.querySelector<HTMLElement>("[data-error]")!.textContent=(error as Error).message}})}catch(error){body.innerHTML=`<p class="legion-empty error">${esc((error as Error).message)}</p>`}};await render()}
async function openLegionApplications(id:number,name:string){const{body}=legionCommunityModal(`${name} · 가입 요청`);const render=async()=>{try{const items=await api<LegionApplication[]>(`/api/parishioner/legion/organizations/${id}/applications`);body.innerHTML=`<div class="legion-application-list">${items.map(item=>`<article><div><strong>${esc(item.name)}${item.baptismalName?` (${esc(item.baptismalName)})`:""}</strong><small>${esc(item.email)} · ${new Date(item.requestedAt).toLocaleString("ko-KR")}</small></div><b class="legion-card-status ${item.status}">${organizationStatuses[item.status]??esc(item.status)}</b><p class="legion-application-motivation"><b>가입 동기</b>${esc(item.motivation)}</p>${item.status==="requested"?`<footer><button data-application="${item.id}" data-status="rejected" type="button">반려</button><button class="green-button" data-application="${item.id}" data-status="approved" type="button">승인</button></footer>`:item.rejectionReason?`<p>반려 사유: ${esc(item.rejectionReason)}</p>`:""}</article>`).join("")||'<p class="legion-empty">가입 요청이 없습니다.</p>'}</div><p data-error></p>`;body.querySelectorAll<HTMLButtonElement>("[data-application]").forEach(button=>button.onclick=async()=>{const status=button.dataset.status!,reason=status==="rejected"?await legionRejectionReason():"";if(status==="rejected"&&!reason)return;if(!await legionPostDecision(status==="approved"?"가입을 승인하시겠습니까?":"가입을 반려하시겠습니까?",status==="approved"?"승인":"반려"))return;try{await api(`/api/parishioner/legion/applications/${button.dataset.application}/decision`,{method:"PATCH",body:JSON.stringify({status,reason})});await render()}catch(error){body.querySelector<HTMLElement>("[data-error]")!.textContent=(error as Error).message}})}catch(error){body.innerHTML=`<p class="legion-empty error">${esc((error as Error).message)}</p>`}};await render()}
