async function openLegionPostsCombined(id:number,name:string,view:"notice"|"board"="notice"){await openLegionViewer(id,name,view);const modal=[...document.querySelectorAll<HTMLElement>(".legion-content-modal")].at(-1),box=modal?.querySelector<HTMLElement>(".member-modal-box");if(!modal||!box)return;const heading=box.querySelector<HTMLElement>(":scope>h3");if(heading)heading.textContent=`${name} · 공지/게시`;const tabs=document.createElement("nav");tabs.className="legion-post-combined-tabs";tabs.setAttribute("role","tablist");tabs.setAttribute("aria-label","공지 및 게시판");tabs.innerHTML=`<button class="${view==="notice"?"active":""}" data-combined-view="notice" type="button" role="tab" aria-selected="${view==="notice"}">공지사항</button><button class="${view==="board"?"active":""}" data-combined-view="board" type="button" role="tab" aria-selected="${view==="board"}">게시판</button>`;(heading?.nextElementSibling?box.insertBefore(tabs,heading.nextElementSibling):box.prepend(tabs));tabs.querySelectorAll<HTMLButtonElement>("[data-combined-view]").forEach(button=>button.onclick=()=>{const next=button.dataset.combinedView as "notice"|"board";if(next===view)return;modal.remove();void openLegionPostsCombined(id,name,next)})}
function mergeLegionPostButtons(){document.querySelectorAll<HTMLElement>("article .legion-card-actions").forEach(actions=>{const notice=actions.querySelector<HTMLButtonElement>('[data-legion-view="notice"]'),board=actions.querySelector<HTMLButtonElement>('[data-legion-view="board"]');if(!notice||!board||actions.querySelector("[data-legion-posts-combined]"))return;const button=document.createElement("button");button.type="button";button.dataset.legionPostsCombined=notice.dataset.org;button.textContent="공지/게시";button.onclick=()=>void openLegionPostsCombined(Number(notice.dataset.org),notice.dataset.name??"조직");actions.insertBefore(button,notice);notice.remove();board.remove()})}
