type PersonalGraceDiary={id:number;title:string;content:string;sourceType:"direct"|"mass";sourceDate:string|null;sourceScheduleId:number|null;createdAt:string;updatedAt:string};
type PersonalGraceDiaryPrefill={title?:string;content?:string;sourceType?:"direct"|"mass";sourceDate?:string;sourceScheduleId?:number};
async function openPersonalGraceDiary(prefill:PersonalGraceDiaryPrefill={}){
  document.querySelector(".personal-grace-diary-modal")?.remove();
  const layer=document.createElement("div");
  layer.className="member-modal legion-content-modal personal-grace-diary-modal";
  layer.innerHTML=`<section class="member-modal-box"><h3>신앙활동 · ${prefill.sourceType==="mass"?"강론 노트":"은총일기"}</h3><div class="legion-content-body"><div class="legion-post-list-head"><div><h4>${prefill.sourceType==="mass"?"강론 노트":"나의 은총일기"}</h4><small>${prefill.sourceType==="mass"?"신부님 말씀 중 마음에 남거나 공감된 한마디를 적어보세요":"나만 확인할 수 있는 개인 신앙 기록입니다."}</small></div><button class="green-button" data-open-post-form type="button">${prefill.sourceType==="mass"?"강론 노트 작성":"일기 등록"}</button></div><form class="legion-post-form" hidden><h4>${prefill.sourceType==="mass"?"강론 노트":"일기 작성"}</h4><label><span>* 제목</span><input name="title" maxlength="300" required placeholder="제목을 입력해 주세요"></label><label><span>* 내용</span><textarea name="content" maxlength="60000" rows="6" required placeholder="${prefill.sourceType==="mass"?"신부님 말씀 중 마음에 남거나 공감된 한마디를 적어보세요":"오늘 받은 은총을 기록해 주세요"}"></textarea></label><div class="legion-story-emojis" aria-label="이모티콘 선택"><span>이모티콘</span>${["😀","😊","🥰","🙏","👏","❤️","👍","🌿","✨"].map(value=>`<button type="button">${value}</button>`).join("")}</div><p data-post-error></p><div class="legion-post-form-actions"><button data-cancel-post type="button">취소</button><button class="green-button" type="submit" disabled>${prefill.sourceType==="mass"?"강론 노트 등록":"일기 등록"}</button></div></form><div data-grace-diary-list><p class="legion-content-loading">불러오는 중...</p></div></div><footer><button data-close type="button">닫기</button></footer></section>`;
  document.body.append(layer);
  const form=layer.querySelector<HTMLFormElement>(".legion-post-form")!,openButton=layer.querySelector<HTMLButtonElement>("[data-open-post-form]")!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,titleInput=form.elements.namedItem("title") as HTMLInputElement,contentInput=form.elements.namedItem("content") as HTMLTextAreaElement,error=form.querySelector<HTMLElement>("[data-post-error]")!,list=layer.querySelector<HTMLElement>("[data-grace-diary-list]")!;
  const sync=()=>submit.disabled=!titleInput.value.trim()||!contentInput.value.trim();
  const closeForm=()=>{form.hidden=true;openButton.hidden=false;form.reset();error.textContent="";sync()};
  const openForm=()=>{openButton.hidden=true;form.hidden=false;titleInput.value=prefill.title??"";contentInput.value=prefill.content??"";sync();(prefill.content?contentInput:titleInput).focus()};
  const load=async()=>{try{const diaries=await api<PersonalGraceDiary[]>("/api/parishioner/grace-diaries");list.innerHTML=diaries.length?`<div class="legion-content-list personal-grace-diary-list">${diaries.map(item=>`<article><header><strong>${esc(item.title)}</strong><time>${new Date(item.createdAt).toLocaleString("ko-KR")}</time></header>${item.sourceType==="mass"?`<small>미사에서 기록${item.sourceDate?` · ${esc(item.sourceDate)}`:""}</small>`:""}<p>${esc(item.content)}</p></article>`).join("")}</div>`:'<p class="legion-empty">아직 작성한 은총일기가 없습니다.</p>'}catch(reason){list.innerHTML=`<p class="legion-empty error">${esc((reason as Error).message)}</p>`}};
  layer.querySelector<HTMLButtonElement>("[data-close]")!.onclick=()=>layer.remove();
  layer.querySelector<HTMLButtonElement>("[data-cancel-post]")!.onclick=closeForm;
  openButton.onclick=openForm;
  form.addEventListener("input",sync);
  form.querySelectorAll<HTMLButtonElement>(".legion-story-emojis button").forEach(button=>button.onclick=()=>{contentInput.setRangeText(button.textContent??"",contentInput.selectionStart,contentInput.selectionEnd,"end");contentInput.focus();sync()});
  form.onsubmit=async event=>{event.preventDefault();sync();if(submit.disabled)return;submit.disabled=true;error.textContent="";try{await api("/api/parishioner/grace-diaries",{method:"POST",body:JSON.stringify({title:titleInput.value.trim(),content:contentInput.value.trim(),sourceType:prefill.sourceType??"direct",sourceDate:prefill.sourceDate??null,sourceScheduleId:prefill.sourceScheduleId??null})});closeForm();await load()}catch(reason){error.textContent=(reason as Error).message;sync()}};
  await load();
  if(prefill.title||prefill.content)openForm();
}
