async function openActivityReportModal(id:number,name:string){const layer=document.createElement("div");layer.className="member-modal legion-content-modal legion-activity-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${esc(name)} · 신앙활동</h3><nav class="legion-post-combined-tabs legion-faith-tabs"><button data-switch-faith="grace_diary" type="button">은총일기</button><button class="active" type="button">활동보고</button></nav><div class="legion-content-body"><form class="legion-activity-form"><div class="legion-activity-date"><label>활동일자<input name="activityDate" type="date" max="${new Date().toISOString().slice(0,10)}" value="${new Date().toISOString().slice(0,10)}" required></label><button class="green-button" type="submit" disabled>활동보고 등록</button></div><nav class="legion-activity-tabs" role="tablist">${legionActivityGroups.map((group,index)=>`<button class="${index===0?"active":""}" data-activity-tab="${index}" type="button">${group.icon} ${esc(group.name)}</button>`).join("")}</nav><div class="legion-activity-groups">${legionActivityGroups.map((group,index)=>`<section data-activity-panel="${index}" ${index?"hidden":""}><header><b>${group.icon} ${esc(group.name)}</b></header>${group.items.map((item,itemIndex)=>`<div class="legion-activity-row"><span>${esc(item)}</span><div><button data-count-step="-1" type="button" aria-label="감소">−</button><input name="count_${index}_${itemIndex}" value="0" inputmode="numeric" readonly><button data-count-step="1" type="button" aria-label="증가">＋</button></div></div>`).join("")}</section>`).join("")}</div><label class="legion-activity-other"><span>항목으로 구분되지 않은 활동 내역</span><textarea name="otherActivity" rows="4" maxlength="5000" placeholder="위 항목에 없는 활동 내용을 자유롭게 입력해 주세요."></textarea></label><p data-activity-error></p></form><section class="legion-activity-history"><h4>등록된 활동보고</h4><div data-activity-history><p class="legion-content-loading">불러오는 중...</p></div></section></div><footer><button data-close type="button">닫기</button></footer></section>`;document.body.append(layer);const form=layer.querySelector<HTMLFormElement>(".legion-activity-form")!,submit=form.querySelector<HTMLButtonElement>('button[type="submit"]')!,other=form.elements.namedItem("otherActivity") as HTMLTextAreaElement,counts=[...form.querySelectorAll<HTMLInputElement>('[name^="count_"]')],sync=()=>submit.disabled=!other.value.trim()&&!counts.some(input=>Number(input.value)>0);layer.querySelector<HTMLButtonElement>("[data-close]")!.onclick=()=>layer.remove();layer.querySelector<HTMLButtonElement>("[data-switch-faith]")!.onclick=()=>{layer.remove();void openFaithActivity(id,name,"grace_diary")};layer.querySelectorAll<HTMLButtonElement>("[data-activity-tab]").forEach(button=>button.onclick=()=>{layer.querySelectorAll("[data-activity-tab]").forEach(tab=>tab.classList.toggle("active",tab===button));layer.querySelectorAll<HTMLElement>("[data-activity-panel]").forEach(panel=>panel.hidden=panel.dataset.activityPanel!==button.dataset.activityTab)});layer.querySelectorAll<HTMLButtonElement>("[data-count-step]").forEach(button=>button.onclick=()=>{const input=button.parentElement!.querySelector<HTMLInputElement>("input")!;input.value=String(Math.max(0,Number(input.value)+Number(button.dataset.countStep)));sync()});other.oninput=sync;const load=async()=>{const posts=await api<LegionPostView[]>(`/api/parishioner/legion/organizations/${id}/posts?type=activity_report`),target=layer.querySelector<HTMLElement>("[data-activity-history]")!;target.innerHTML=posts.length?posts.map(post=>{let summary=post.content;try{const parsed=JSON.parse(post.content) as{counts:Record<string,number>;other:string};const total=Object.values(parsed.counts).reduce((sum,value)=>sum+Number(value),0);summary=`총 활동 ${total}회${parsed.other?` · ${parsed.other}`:""}`}catch{}return`<article><div><strong>${esc(post.title)}</strong><small>${new Date(post.createdAt).toLocaleString("ko-KR")}</small></div><p>${esc(summary)}</p></article>`}).join(""):'<p class="legion-empty">등록된 활동보고가 없습니다.</p>'};form.onsubmit=async event=>{event.preventDefault();sync();if(submit.disabled)return;const password=await legionPostPasswordConfirm("활동보고를 등록하시겠습니까?","활동보고 등록");if(!password)return;const values=Object.fromEntries(counts.filter(input=>Number(input.value)>0).map(input=>[input.name,Number(input.value)])),date=(form.elements.namedItem("activityDate") as HTMLInputElement).value,error=form.querySelector<HTMLElement>("[data-activity-error]")!;submit.disabled=true;try{await api(`/api/parishioner/legion/organizations/${id}/posts`,{method:"POST",body:JSON.stringify({postType:"activity_report",title:`${date} 활동보고`,content:JSON.stringify({counts:values,other:other.value.trim()}),password})});form.reset();counts.forEach(input=>input.value="0");sync();await load()}catch(reason){error.textContent=(reason as Error).message;sync()}};sync();void load()}
async function openFaithActivity(id:number,name:string,view:"grace_diary"|"activity_report"="grace_diary"){if(view==="activity_report")return openActivityReportModal(id,name);await openLegionViewer(id,name,view);const modal=[...document.querySelectorAll<HTMLElement>(".legion-content-modal")].at(-1),box=modal?.querySelector<HTMLElement>(".member-modal-box");if(!modal||!box)return;const heading=box.querySelector<HTMLElement>(":scope>h3");if(heading)heading.textContent=`${name} · 신앙활동`;const tabs=document.createElement("nav");tabs.className="legion-post-combined-tabs legion-faith-tabs";tabs.setAttribute("role","tablist");tabs.setAttribute("aria-label","신앙활동");tabs.innerHTML=`<button class="${view==="grace_diary"?"active":""}" data-faith-view="grace_diary" type="button" role="tab" aria-selected="${view==="grace_diary"}">은총일기</button><button class="${view==="activity_report"?"active":""}" data-faith-view="activity_report" type="button" role="tab" aria-selected="${view==="activity_report"}">활동보고</button>`;(heading?.nextElementSibling?box.insertBefore(tabs,heading.nextElementSibling):box.prepend(tabs));tabs.querySelectorAll<HTMLButtonElement>("[data-faith-view]").forEach(button=>button.onclick=()=>{const next=button.dataset.faithView as "grace_diary"|"activity_report";if(next===view)return;modal.remove();void openFaithActivity(id,name,next)})}
function removePraesidiumFaithButtons(){document.querySelectorAll(".legion-praesidium [data-legion-faith]").forEach(button=>button.remove())}
async function openFaithActivityFromMainMenu(view:"grace_diary"|"activity_report"){if(view==="grace_diary")return openPersonalGraceDiary();try{const organizations=await api<Org[]>("/api/parishioner/legion/organizations"),praesidium=organizations.find(item=>item.organizationType==="praesidium"&&item.role!=="visitor");if(!praesidium)throw new Error("활동보고를 등록할 소속 쁘레시디움이 없습니다.");void openFaithActivity(praesidium.id,praesidium.name,view)}catch(error){showLegionResult((error as Error).message,false)}}
document.addEventListener("click",event=>{const button=(event.target as Element).closest<HTMLButtonElement>(".legion-activity-modal [data-switch-faith]");if(!button)return;event.preventDefault();event.stopImmediatePropagation();button.closest(".legion-activity-modal")?.remove();void openPersonalGraceDiary()},true);
document.addEventListener("member:personal-grace-diary",event=>{const detail=(event as CustomEvent<{scheduleId:number;scheduleDate:string;title:string;scheduleType:string|null}>).detail;void openPersonalGraceDiary({title:`${detail.scheduleDate} ${detail.title}`,content:"",sourceType:"mass",sourceDate:detail.scheduleDate,sourceScheduleId:detail.scheduleId})});
