document.addEventListener("member:mass-grace-diary",event=>{const detail=(event as CustomEvent<{scheduleDate:string;title:string;scheduleType:string|null}>).detail;void(async()=>{try{const organizations=await api<Org[]>("/api/parishioner/legion/organizations"),praesidium=organizations.find(item=>item.organizationType==="praesidium"&&item.role!=="visitor");if(!praesidium)throw new Error("강론 노트를 기록할 소속 쁘레시디움이 없습니다.");await openFaithActivity(praesidium.id,praesidium.name,"grace_diary");const modal=[...document.querySelectorAll<HTMLElement>(".legion-content-modal")].at(-1),open=modal?.querySelector<HTMLButtonElement>("[data-open-post-form]");open?.click();const form=modal?.querySelector<HTMLFormElement>(".legion-post-form"),title=form?.elements.namedItem("title") as HTMLInputElement|null,content=form?.elements.namedItem("content") as HTMLTextAreaElement|null;if(title)title.value=`${detail.scheduleDate} ${detail.title}`;if(content){content.value="";content.placeholder="신부님 말씀 중 마음에 남거나 공감된 한마디를 적어보세요";content.focus()}form?.dispatchEvent(new Event("input",{bubbles:true}))}catch(error){showLegionResult((error as Error).message,false)}})()});
