type LegionMemorial={id:number;name:string;baptismalName:string|null;deathDate:string;biography:string;coverPhotoId:number|null;messageCount:number;prayerCount:number};
const legionFileBase64=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(",")[1]??"");reader.onerror=()=>reject(new Error("사진을 읽지 못했습니다."));reader.readAsDataURL(file)});
async function openPraesidiumMemorials(organizationId:number,organizationName:string){document.querySelector(".legion-memorial-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal legion-content-modal legion-memorial-modal";layer.innerHTML=`<section class="member-modal-box"><h3>${esc(organizationName)} · 추모의 공간</h3><div class="legion-memorial-body">불러오는 중입니다.</div><footer><button class="green-outline" data-close type="button">닫기</button></footer></section>`;document.body.append(layer);layer.querySelector("[data-close]")!.addEventListener("click",()=>layer.remove());try{const items=await api<LegionMemorial[]>(`/api/parishioner/legion/organizations/${organizationId}/memorials`),body=layer.querySelector<HTMLElement>(".legion-memorial-body")!;body.innerHTML=`<header><div><h4>함께 기억하고 기도합니다</h4><p>추모 대상과 참여자는 이 쁘레시디움의 단원으로 제한됩니다.</p></div><button class="green-button" data-create type="button">+ 추모 공간 등록</button></header><div class="legion-memorial-list">${items.map(item=>`<article>${item.coverPhotoId?`<img src="/api/parishioner/legion/memorial-photos/${item.coverPhotoId}" alt="${esc(item.name)}">`:'<div class="legion-memorial-placeholder">✝</div>'}<div><h4>${esc(item.name)}${item.baptismalName?` <small>(${esc(item.baptismalName)})</small>`:""}</h4><time>${item.deathDate} 선종</time><p>${esc(item.biography)}</p><footer><span>추모 메시지 ${item.messageCount} · 기도문 ${item.prayerCount}</span><button class="green-outline" data-detail="${item.id}" type="button">상세보기</button></footer></div></article>`).join("")||'<p class="legion-empty">등록된 추모 공간이 없습니다.</p>'}</div>`;body.querySelector<HTMLButtonElement>("[data-create]")!.onclick=()=>void openPraesidiumMemorialForm(organizationId,organizationName);body.querySelectorAll<HTMLButtonElement>("[data-detail]").forEach(button=>button.onclick=()=>void openPraesidiumMemorialDetail(Number(button.dataset.detail),organizationId,organizationName))}catch(error){layer.querySelector<HTMLElement>(".legion-memorial-body")!.textContent=(error as Error).message}}
async function openPraesidiumMemorialForm(organizationId:number,organizationName:string){try{const members=await api<Array<{id:number;name:string;baptismalName:string|null;role:string}>>(`/api/parishioner/legion/organizations/${organizationId}/memorial-members`);document.querySelector(".legion-memorial-form-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal legion-memorial-form-modal";layer.innerHTML=`<section class="member-modal-box"><h3>추모 공간 등록</h3><form><label>* 추모 대상 단원<select name="subjectMemberId" required><option value="">단원을 선택해 주세요</option>${members.map(member=>`<option value="${member.id}">${esc(member.name)}${member.baptismalName?` (${esc(member.baptismalName)})`:""} · ${esc(roles[member.role]??member.role)}</option>`).join("")}</select></label><label>* 선종일<input name="deathDate" type="date" max="${new Date(Date.now()+9*60*60*1000).toISOString().slice(0,10)}" required></label><label class="full">* 약력<textarea name="biography" maxlength="20000" rows="5" required></textarea></label><label class="full">* 사진 <small>1~5장, 장당 2MB</small><input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label><p data-error></p><footer><button class="green-outline" data-cancel type="button">취소</button><button class="green-button" type="submit">등록</button></footer></form></section>`;document.body.append(layer);layer.querySelector("[data-cancel]")!.addEventListener("click",()=>layer.remove());const form=layer.querySelector<HTMLFormElement>("form")!;form.onsubmit=async event=>{event.preventDefault();const error=form.querySelector<HTMLElement>("[data-error]")!,files=[...((form.elements.namedItem("photos") as HTMLInputElement).files??[])];if(files.length<1||files.length>5||files.some(file=>file.size>2*1024*1024)){error.textContent="사진은 1~5장, 장당 2MB 이하로 선택해 주세요.";return}try{const photos=await Promise.all(files.map(async file=>({type:file.type,data:await legionFileBase64(file)})));await api(`/api/parishioner/legion/organizations/${organizationId}/memorials`,{method:"POST",body:JSON.stringify({subjectMemberId:Number((form.elements.namedItem("subjectMemberId") as HTMLSelectElement).value),deathDate:(form.elements.namedItem("deathDate") as HTMLInputElement).value,biography:(form.elements.namedItem("biography") as HTMLTextAreaElement).value,photos})});layer.remove();document.querySelector(".legion-memorial-modal")?.remove();void openPraesidiumMemorials(organizationId,organizationName)}catch(reason){error.textContent=(reason as Error).message}}}catch(error){showLegionResult((error as Error).message,false)}}
async function openPraesidiumMemorialDetail(memorialId:number,organizationId:number,organizationName:string){document.querySelector(".legion-memorial-detail-modal")?.remove();const layer=document.createElement("div");layer.className="member-modal legion-memorial-detail-modal";layer.innerHTML='<section class="member-modal-box"><h3>추모의 공간</h3><div class="member-modal-body">불러오는 중입니다.</div><footer><button class="green-outline" data-close type="button">닫기</button></footer></section>';document.body.append(layer);layer.querySelector("[data-close]")!.addEventListener("click",()=>layer.remove());try{const item=await api<any>(`/api/parishioner/legion/memorials/${memorialId}`),body=layer.querySelector<HTMLElement>(".member-modal-body")!;body.innerHTML=`<div class="legion-memorial-gallery">${item.photos.map((photo:any)=>`<img src="/api/parishioner/legion/memorial-photos/${photo.id}" alt="${esc(item.name)}">`).join("")}</div><h4>${esc(item.name)}${item.baptismalName?` (${esc(item.baptismalName)})`:""}</h4><p>${esc(item.deathDate)} 선종</p><p>${esc(item.biography)}</p><section class="legion-memorial-entries">${item.entries.map((entry:any)=>`<article><b>${entry.entryType==="prayer"?"기도문":"추모 메시지"}</b><strong>${esc(entry.authorName)}${entry.baptismalName?` (${esc(entry.baptismalName)})`:""}</strong><p>${esc(entry.content)}</p></article>`).join("")||"<p>아직 남겨진 글이 없습니다.</p>"}<form><select name="entryType"><option value="message">추모 메시지</option><option value="prayer">기도문</option></select><textarea name="content" maxlength="3000" required placeholder="마음을 담아 글을 남겨 주세요."></textarea><button class="green-button" type="submit">남기기</button></form></section>`;body.querySelector<HTMLFormElement>("form")!.onsubmit=async event=>{event.preventDefault();const form=event.currentTarget as HTMLFormElement;await api(`/api/parishioner/legion/memorials/${memorialId}/entries`,{method:"POST",body:JSON.stringify({entryType:(form.elements.namedItem("entryType") as HTMLSelectElement).value,content:(form.elements.namedItem("content") as HTMLTextAreaElement).value})});layer.remove();void openPraesidiumMemorialDetail(memorialId,organizationId,organizationName)}}catch(error){layer.querySelector<HTMLElement>(".member-modal-body")!.textContent=(error as Error).message}}
function mountPraesidiumMemorialButtons(){document.querySelectorAll<HTMLElement>(".legion-praesidium .legion-card-actions").forEach(actions=>{if(actions.querySelector("[data-legion-memorial]"))return;const source=actions.querySelector<HTMLButtonElement>("[data-org]");if(!source)return;const button=document.createElement("button");button.type="button";button.dataset.legionMemorial=source.dataset.org;button.textContent="추모의 공간";button.onclick=()=>void openPraesidiumMemorials(Number(source.dataset.org),source.dataset.name??"쁘레시디움");actions.append(button)})}
