function mountLegionMemorialDropzone(){const modal=document.querySelector<HTMLElement>(".legion-memorial-form-modal"),input=modal?.querySelector<HTMLInputElement>('input[name="photos"]');if(!modal||!input||input.dataset.dropzoneMounted)return;input.dataset.dropzoneMounted="1";const label=input.closest("label")!;label.classList.add("legion-memorial-dropzone-label");const zone=document.createElement("div");zone.className="legion-memorial-dropzone";zone.tabIndex=0;zone.setAttribute("role","button");zone.setAttribute("aria-label","추모 사진 선택 또는 드래그 앤 드롭");zone.innerHTML='<strong>사진을 끌어 놓으세요</strong><span>또는 클릭하여 사진 선택</span><em>JPG, PNG, WEBP · 1~5장 · 장당 2MB</em>';input.insertAdjacentElement("beforebegin",zone);input.classList.add("legion-memorial-file-input");const status=document.createElement("p");status.className="legion-memorial-file-status";input.insertAdjacentElement("afterend",status);const render=()=>{const files=[...(input.files??[])];status.textContent=files.length?`${files.length}장 선택 · ${files.map(file=>file.name).join(", ")}`:"선택된 사진이 없습니다.";zone.classList.toggle("has-files",files.length>0)};zone.onclick=()=>input.click();zone.onkeydown=event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();input.click()}};for(const type of ["dragenter","dragover"])zone.addEventListener(type,event=>{event.preventDefault();zone.classList.add("dragging")});for(const type of ["dragleave","drop"])zone.addEventListener(type,event=>{event.preventDefault();zone.classList.remove("dragging")});zone.addEventListener("drop",event=>{const files=[...(event.dataTransfer?.files??[])].filter(file=>/^image\/(jpeg|png|webp)$/i.test(file.type)).slice(0,5),transfer=new DataTransfer();files.forEach(file=>transfer.items.add(file));input.files=transfer.files;input.dispatchEvent(new Event("change",{bubbles:true}));render()});input.addEventListener("change",render);render()}
